 jetons en croix : un jeton au centre et quatre branches de 1, 2 puis 3 jetons, soit 5, 9 puis 13 jetons.\n---\nJ1k0 = point(1, 3, visible=faux)\ncercle(J1k0, rayon=0.3, couleur=\"bleu\", remplissage=\"bleu\", opacite_fond=1)\nJ1k1 = point(0, 3, visible=faux)\ncercle(J1k1, rayon=0.3, couleur=\"bleu\", remplissage=\"bleu\", opacite_fond=1)\nJ1k2 = point(2, 3, visible=faux)\ncercle(J1k2, rayon=0.3, couleur=\"bleu\", remplissage=\"bleu\", opacite_fond=1)\nJ1k3 = point(1, 2, visible=faux)\ncercle(J1k3, rayon=0.3, couleur=\"bleu\", remplissage=\"bleu\", opacite_fond=1)\nJ1k4 = point(1, 4, visible=faux)\ncercle(J1k4, rayon=0.3, couleur=\"bleu\", remplissage=\"bleu\", opacite_fond=1)\ntexte(1, -1, \"Étape 1\")\nJ2k0 = point(5.5, 3, visible=faux)\ncercle(J2k0, rayon=0.3, couleur=\"bleu\", remplissage=\"bleu\", opacite_fond=1)\nJ2k1 = point(4.5, 3, visible=faux)\ncercle(J2k1, rayon=0.3, couleur=\"bleu\", remplissage=\"bleu\", opacite_fond=1)\nJ2k2 = point(6.5, 3, visible=faux)\ncercle(J2k2, rayon=0.3, couleur=\"bleu\", remplissage=\"bleu\", opacite_fond=1)\nJ2k3 = point(5.5, 2, visible=faux)\ncercle(J2k3, rayon=0.3, couleur=\"bleu\", remplissage=\"bleu\", opacite_fond=1)\nJ2k4 = point(5.5, 4, visible=faux)\ncercle(J2k4, rayon=0.3, couleur=\"bleu\", remplissage=\"bleu\", opacite_fond=1)\nJ2k5 = point(3.5, 3, visible=faux)\ncercle(J2k5, rayon=0.3, couleur=\"bleu\", remplissage=\"bleu\", opacite_fond=1)\nJ2k6 = point(7.5, 3, visible=faux)\ncercle(J2k6, rayon=0.3, couleur=\"bleu\", remplissage=\"bleu\", opacite_fond=1)\nJ2k7 = point(5.5, 1, visible=faux)\ncercle(J2k7, rayon=0.3, couleur=\"bleu\", remplissage=\"bleu\", opacite_fond=1)\nJ2k8 = point(5.5, 5, visible=faux)\ncercle(J2k8, rayon=0.3, couleur=\"bleu\", remplissage=\"bleu\", opacite_fond=1)\ntexte(5.5, -1, \"Étape 2\")\nJ3k0 = point(12, 3, visible=faux)\ncercle(J3k0, rayon=0.3, couleur=\"bleu\", remplissage=\"bleu\", opacite_fond=1)\nJ3k1 = point(11, 3, visible=faux)\ncercle(J3k1, rayon=0.3, couleur=\"bleu\", remplissage