eu\", opacite_fond=1, visible={{if:0<3+c && 0<r|vrai|faux}})\nJ301 = point({{eval:0+(1+c+1.5)+(2+c+1.5)+0;d}}, 1, visible=faux)\ncercle(J301, rayon=0.3, couleur=\"bleu\", remplissage=\"bleu\", opacite_fond=1, visible={{if:0<3+c && 1<r|vrai|faux}})\nJ302 = point({{eval:0+(1+c+1.5)+(2+c+1.5)+0;d}}, 2, visible=faux)\ncercle(J302, rayon=0.3, couleur=\"bleu\", remplissage=\"bleu\", opacite_fond=1, visible={{if:0<3+c && 2<r|vrai|faux}})\nJ303 = point({{eval:0+(1+c+1.5)+(2+c+1.5)+0;d}}, 3, visible=faux)\ncercle(J303, rayon=0.3, couleur=\"bleu\", remplissage=\"bleu\", opacite_fond=1, visible={{if:0<3+c && 3<r|vrai|faux}})\nJ310 = point({{eval:0+(1+c+1.5)+(2+c+1.5)+1;d}}, 0, visible=faux)\ncercle(J310, rayon=0.3, couleur=\"bleu\", remplissage=\"bleu\", opacite_fond=1, visible={{if:1<3+c && 0<r|vrai|faux}})\nJ311 = point({{eval:0+(1+c+1.5)+(2+c+1.5)+1;d}}, 1, visible=faux)\ncercle(J311, rayon=0.3, couleur=\"bleu\", remplissage=\"bleu\", opacite_fond=1, visible={{if:1<3+c && 1<r|vrai|faux}})\nJ312 = point({{eval:0+(1+c+1.5)+(2+c+1.5)+1;d}}, 2, visible=faux)\ncercle(J312, rayon=0.3, couleur=\"bleu\", remplissage=\"bleu\", opacite_fond=1, visible={{if:1<3+c && 2<r|vrai|faux}})\nJ313 = point({{eval:0+(1+c+1.5)+(2+c+1.5)+1;d}}, 3, visible=faux)\ncercle(J313, rayon=0.3, couleur=\"bleu\", remplissage=\"bleu\", opacite_fond=1, visible={{if:1<3+c && 3<r|vrai|faux}})\nJ320 = point({{eval:0+(1+c+1.5)+(2+c+1.5)+2;d}}, 0, visible=faux)\ncercle(J320, rayon=0.3, couleur=\"bleu\", remplissage=\"bleu\", opacite_fond=1, visible={{if:2<3+c && 0<r|vrai|faux}})\nJ321 = point({{eval:0+(1+c+1.5)+(2+c+1.5)+2;d}}, 1, visible=faux)\ncercle(J321, rayon=0.3, couleur=\"bleu\", remplissage=\"bleu\", opacite_fond=1, visible={{if:2<3+c && 1<r|vrai|faux}})\nJ322 = point({{eval:0+(1+c+1.5)+(2+c+1.5)+2;d}}, 2, visible=faux)\ncercle(J322, rayon=0.3, couleur=\"bleu\", remplissage=\"bleu\", opacite_fond=1, visible={{if:2<3+c && 2<r|vrai|faux}})\nJ323 = point({{eval:0+(1+c+1.5)+(2+c+1.5)+2;d}}, 3, visible=faux)\nc