os}}}} ?\n\n{{if:t==0|Lapins|{{if:t==1|Chats|Voitures}}}} : $?$\n\n{{if:t==0|Poules|{{if:t==1|Oiseaux|Motos}}}} : $?$","variables":[{"name":"t","expression":"0..2"},{"name":"x","expression":"2..10"},{"name":"y","expression":"2..10"},{"name":"h","expression":"eval:x+y"},{"name":"m","expression":"eval:4*x+2*y"}],"conditions":["x!=y","mod(y,2)==0","y!=2*x"],"blanks":[{"expectedAnswer":"{{x}}","expectedErrors":[{"answer":"{{y}}","message":"C'est le nombre de {{if:t==0|poules|{{if:t==1|oiseaux|motos}}}} : vérifie l'ordre des cases.","label":"Nombres inversés"},{"answer":"{{eval:h/2}}","message":"Avec autant de {{if:t==0|lapins|{{if:t==1|chats|voitures}}}} que de {{if:t==0|poules|{{if:t==1|oiseaux|motos}}}}, il y aurait ${{eval:3*h}}$ {{if:t==0|pattes|{{if:t==1|pattes|roues}}}}, pas ${{m}}$.","label":"Total partagé en deux"},{"answer":"{{eval:m/4}}","message":"En divisant les ${{m}}$ {{if:t==0|pattes|{{if:t==1|pattes|roues}}}} par $4$, tu fais comme s'il n'y avait que des {{if:t==0|lapins|{{if:t==1|chats|voitures}}}} : les {{if:t==0|poules|{{if:t==1|oiseaux|motos}}}} n'en ont que $2$.","label":"{{if:t==0|pattes|{{if:t==1|pattes|roues}}}} divisées par 4"}]},{"expectedAnswer":"{{y}}","expectedErrors":[{"answer":"{{x}}","message":"C'est le nombre de {{if:t==0|lapins|{{if:t==1|chats|voitures}}}} : vérifie l'ordre des cases.","label":"Nombres inversés"},{"answer":"{{eval:h/2}}","message":"Il n'y a pas autant de {{if:t==0|poules|{{if:t==1|oiseaux|motos}}}} que de {{if:t==0|lapins|{{if:t==1|chats|voitures}}}} : on aurait alors ${{eval:3*h}}$ {{if:t==0|pattes|{{if:t==1|pattes|roues}}}}, pas ${{m}}$.","label":"Total partagé en deux"},{"answer":"{{eval:h-m/4}}","message":"${{m}} \\div 4 = {{eval:m/4}}$ n'est pas le nombre de {{if:t==0|lapins|{{if:t==1|chats|voitures}}}} : les {{if:t==0|poules|{{if:t==1|oiseaux|motos}}}} n'ont que $2$ {{if:t==0|pattes|{{if:t==1|pattes|roues}}}}.","label":"{{if:t==0|pattes|{{if:t==1|pattes|roues}}}} divisées par 4"}]}],"correction":{"steps":["**Et s'