p)/100;d2}}}} + {{x}} \\times {{if:mod(g,100)==0|{{eval:(g)/100;d}}|{{eval:(g)/100;d2}}}} = {{if:mod(p*y,100)==0|{{eval:(p*y)/100;d}}|{{eval:(p*y)/100;d2}}}} + {{if:mod(g*x,100)==0|{{eval:(g*x)/100;d}}|{{eval:(g*x)/100;d2}}}} = {{if:mod(s,100)==0|{{eval:(s)/100;d}}|{{eval:(s)/100;d2}}}}$."]},"hint":"Et s'il n'y avait que des pièces de {{if:c==0|$20$ centimes|$50$ centimes}} ?"}]$q$::jsonb
