-- 	select true, q.variations = $q$[{"hint":"Compare les deux pesées : qu'y a-t-il en plus sur la première balance ?","blanks":[{"expectedAnswer":"{{eval:B}}","expectedErrors":[{"label":"Différence non partagée","answer":"{{eval:((a-1)*B)}}","message":"C'est la masse de ${{eval:a-1}}$ boules : partage-la entre elles."},{"label":"Pesée partagée entre tous les objets","answer":"{{eval:(a*B+E)/(a+1)}}","message":"Les objets n'ont pas tous la même masse : on ne peut pas partager la première pesée en parts égales."},{"label":"Boule et étoile échangées","answer":"{{eval:E}}","message":"C'est la masse d'une étoile : vérifie quelle case est celle de la boule."}]},{"expectedAnswer":"{{eval:E}}","expectedErrors":[{"label":"Deuxième pesée partagée en deux","answer":"{{eval:(B+E)/2}}","message":"Une boule et une étoile n'ont pas la même masse : on ne peut pas partager la deuxième pesée en deux."},{"label":"Différence non partagée retirée","answer":"{{eval:(E-(a-2)*B)}}","message":"Tu as retiré la masse de ${{eval:a-1}}$ boules : sur la deuxième pesée, il n'y a qu'une boule."},{"label":"Boule et étoile échangées","answer":"{{eval:B}}","message":"C'est la masse d'une boule : vérifie quelle case est celle de l'étoile."}]}],"statement":"Les boules (B) sont toutes identiques, les étoiles (E) aussi. Voici deux pesées : chaque fois, la balance est en équilibre.\n\n{{if:a==2|```figure\nfenetre: 0 ; 9 ; -0.4 ; 2.6\ndescription: Première pesée : à gauche 2 boules B et 1 étoile E, à droite une masse de {{eval:2*B+E}} g.\n---\nS1 = point(3.95, 0, visible=faux)\nS2 = point(5.05, 0, visible=faux)\nS3 = point(4.5, 1.15, visible=faux)\npolygone(S1, S2, S3, couleur=\"noir\", remplissage=\"gris\", opacite_fond=1)\nF1 = point(0.3, 1.2, visible=faux)\nF2 = point(8.7, 1.2, visible=faux)\nsegment(F1, F2, epaisseur=4)\nO0a = point(0.4, 1.3, visible=faux)\nO0b = point(1.2, 1.3, visible=faux)\nO0c = point(1.2, 2.2, visible=faux)\nO0d = point(0.4, 2.2, visible=faux)\npolygone(O0a, O0b, O0c, O0d, couleur=\"noir\", remplissage=\"jaune\", opacite_fond=0.3)\ntexte(0.8, 1.75, \"B\")\nO1a = point(1.3, 1.3, visible=faux)\nO1b = point(2.1, 1.3, visible=faux)\nO1c = point(2.1, 2.2, visible=faux)\nO1d = point(1.3, 2.2, visible=faux)\npolygone(O1a, O1b, O1c, O1d, couleur=\"noir\", remplissage=\"jaune\", opacite_fond=0.3)\ntexte(1.7, 1.75, \"B\")\nO2a = point(2.2, 1.3, visible=faux)\nO2b = point(3.0, 1.3, visible=faux)\nO2c = point(3.0, 2.2, visible=faux)\nO2d = point(2.2, 2.2, visible=faux)\npolygone(O2a, O2b, O2c, O2d, couleur=\"noir\", remplissage=\"jaune\", opacite_fond=0.3)\ntexte(2.6, 1.75, \"E\")\nD1 = point(5.3, 1.3, visible=faux)\nD2 = point(7.9, 1.3, visible=faux)\nD3 = point(7.9, 2.2, visible=faux)\nD4 = point(5.3, 2.2, visible=faux)\npolygone(D1, D2, D3, D4, couleur=\"noir\", remplissage=\"jaune\", opacite_fond=0.3)\ntexte(6.6, 1.75, \"{{eval:2*B+E}} g\")\n```|{{if:a==3|```figure\nfenetre: 0 ; 9 ; -0.4 ; 2.6\ndescription: Première pesée : à gauche 3 boules B et 1 étoile E, à droite une masse de {{eval:3*B+E}} g.\n---\nS1 = point(3.95, 0, visible=faux)\nS2 = point(5.05, 0, visible=faux)\nS3 = point(4.5, 1.15, visible=faux)\npolygone(S1, S2, S3, couleur=\"noir\", remplissage=\"gris\", opacite_fond=1)\nF1 = point(0.3, 1.2, visible=faux)\nF2 = point(8.7, 1.2, visible=faux)\nsegment(F1, F2, epaisseur=4)\nO0a = point(0.4, 1.3, visible=faux)\nO0b = point(1.2, 1.3, visible=faux)\nO0c = point(1.2, 2.2, visible=faux)\nO0d = point(0.4, 2.2, visible=faux)\npolygone(O0a, O0b, O0c, O0d, couleur=\"noir\", remplissage=\"jaune\", opacite_fond=0.3)\ntexte(0.8, 1.75, \"B\")\nO1a = point(1.3, 1.3, visible=faux)\nO1b = point(2.1, 1.3, visible=faux)\nO1c = point(2.1, 2.2, visible=faux)\nO1d = point(1.3, 2.2, visible=faux)\npolygone(O1a, O1b, O1c, O1d, couleur=\"noir\", remplissage=\"jaune\", opacite_fond=0.3)\ntexte(1.7, 1.75, \"B\")\nO2a = point(2.2, 1.3, visible=faux)\nO2b = point(3.0, 1.3, visible=faux)\nO2c = point(3.0, 2.2, visible=faux)\nO2d = point(2.2, 2.2, visible=faux)\npolygone(O2a, O2b, O2c, O2d, couleur=\"noir\", remplissage=\"jaune\", opacite_fond=0.3)\ntexte(2.6, 1.75, \"B\")\nO3a = point(3.1, 1.3, visible=faux)\nO3b = point(3.9, 1.3, visible=faux)\nO3c = point(3.9, 2.2, visible=faux)\nO3d = point(3.1, 2.2, visible=faux)\npolygone(O3a, O3b, O3c, O3d, couleur=\"noir\", remplissage=\"jaune\", opacite_fond=0.3)\ntexte(3.5, 1.75, \"E\")\nD1 = point(5.3, 1.3, visible=faux)\nD2 = point(7.9, 1.3, visible=faux)\nD3 = point(7.9, 2.2, visible=faux)\nD4 = point(5.3, 2.2, visible=faux)\npolygone(D1, D2, D3, D4, couleur=\"noir\", remplissage=\"jaune\", opacite_fond=0.3)\ntexte(6.6, 1.75, \"{{eval:3*B+E}} g\")\n```|```figure\nfenetre: 0 ; 9 ; -0.4 ; 3.6\ndescription: Première pesée : à gauche 4 boules B et 1 étoile E, à droite une masse de {{eval:4*B+E}} g.\n---\nS1 = point(3.95, 0, visible=faux)\nS2 = point(5.05, 0, visible=faux)\nS3 = point(4.5, 1.15, visible=faux)\npolygone(S1, S2, S3, couleur=\"noir\", remplissage=\"gris\", opacite_fond=1)\nF1 = point(0.3, 1.2, visible=faux)\nF2 = point(8.7, 1.2, visible=faux)\nsegment(F1, F2, epaisseur=4)\nO0a = point(0.4, 1.3, visible=faux)\nO0b = point(1.2, 1.3, visible=faux)\nO0c = point(1.2, 2.2, visible=faux)\nO0d = point(0.4, 2.2, visible=faux)\npolygone(O0a, O0b, O0c, O0d, couleur=\"noir\", remplissage=\"jaune\", opacite_fond=0.3)\ntexte(0.8, 1.75, \"B\")\nO1a = point(1.3, 1.3, visible=faux)\nO1b = point(2.1, 1.3, visible=faux)\nO1c = point(2.1, 2.2, visible=faux)\nO1d = point(1.3, 2.2, visible=faux)\npolygone(O1a, O1b, O1c, O1d, couleur=\"noir\", remplissage=\"jaune\", opacite_fond=0.3)\ntexte(1.7, 1.75, \"B\")\nO2a = point(2.2, 1.3, visible=faux)\nO2b = point(3.0, 1.3, visible=faux)\nO2c = point(3.0, 2.2, visible=faux)\nO2d = point(2.2, 2.2, visible=faux)\npolygone(O2a, O2b, O2c, O2d, couleur=\"noir\", remplissage=\"jaune\", opacite_fond=0.3)\ntexte(2.6, 1.75, \"B\")\nO3a = point(3.1, 1.3, visible=faux)\nO3b = point(3.9, 1.3, visible=faux)\nO3c = point(3.9, 2.2, visible=faux)\nO3d = point(3.1, 2.2, visible=faux)\npolygone(O3a, O3b, O3c, O3d, couleur=\"noir\", remplissage=\"jaune\", opacite_fond=0.3)\ntexte(3.5, 1.75, \"B\")\nO4a = point(0.4, 2.3, visible=faux)\nO4b = point(1.2, 2.3, visible=faux)\nO4c = point(1.2, 3.2, visible=faux)\nO4d = point(0.4, 3.2, visible=faux)\npolygone(O4a, O4b, O4c, O4d, couleur=\"noir\", remplissage=\"jaune\", opacite_fond=0.3)\ntexte(0.8, 2.75, \"E\")\nD1 = point(5.3, 1.3, visible=faux)\nD2 = point(7.9, 1.3, visible=faux)\nD3 = point(7.9, 2.2, visible=faux)\nD4 = point(5.3, 2.2, visible=faux)\npolygone(D1, D2, D3, D4, couleur=\"noir\", remplissage=\"jaune\", opacite_fond=0.3)\ntexte(6.6, 1.75, \"{{eval:4*B+E}} g\")\n```}}}}\n\n```figure\nfenetre: 0 ; 9 ; -0.4 ; 2.6\ndescription: Deuxième pesée : à gauche 1 boule B et 1 étoile E, à droite une masse de {{eval:B+E}} g.\n---\nS1 = point(3.95, 0, visible=faux)\nS2 = point(5.05, 0, visible=faux)\nS3 = point(4.5, 1.15, visible=faux)\npolygone(S1, S2, S3, couleur=\"noir\", remplissage=\"gris\", opacite_fond=1)\nF1 = point(0.3, 1.2, visible=faux)\nF2 = point(8.7, 1.2, visible=faux)\nsegment(F1, F2, epaisseur=4)\nO0a = point(0.4, 1.3, visible=faux)\nO0b = point(1.2, 1.3, visible=faux)\nO0c = point(1.2, 2.2, visible=faux)\nO0d = point(0.4, 2.2, visible=faux)\npolygone(O0a, O0b, O0c, O0d, couleur=\"noir\", remplissage=\"jaune\", opacite_fond=0.3)\ntexte(0.8, 1.75, \"B\")\nO1a = point(1.3, 1.3, visible=faux)\nO1b = point(2.1, 1.3, visible=faux)\nO1c = point(2.1, 2.2, visible=faux)\nO1d = point(1.3, 2.2, visible=faux)\npolygone(O1a, O1b, O1c, O1d, couleur=\"noir\", remplissage=\"jaune\", opacite_fond=0.3)\ntexte(1.7, 1.75, \"E\")\nD1 = point(5.3, 1.3, visible=faux)\nD2 = point(7.9, 1.3, visible=faux)\nD3 = point(7.9, 2.2, visible=faux)\nD4 = point(5.3, 2.2, visible=faux)\npolygone(D1, D2, D3, D4, couleur=\"noir\", remplissage=\"jaune\", opacite_fond=0.3)\ntexte(6.6, 1.75, \"{{eval:B+E}} g\")\n```\n\nQuelle est la masse d'une boule ? Quelle est la masse d'une étoile ?\n\nUne boule pèse $?$ g.\n\nUne étoile pèse $?$ g.","variables":[{"name":"a","expression":"2..4"},{"name":"B","expression":"20..50"},{"name":"E","expression":"20..50"}],"conditions":["B!=E"],"correction":{"steps":["**Comparer les pesées.** La première a ${{eval:a-1}}$ boule{{if:a>2|s|}} de plus que la deuxième ; tout le reste est pareil. La différence des masses, c'est donc ${{eval:a-1}}$ boule{{if:a>2|s|}} : ${{eval:(a*B+E)}} - {{eval:(B+E)}} = {{eval:((a-1)*B)}}$.","**Une boule.** {{if:a>2|${{eval:((a-1)*B)}} \\div {{eval:a-1}} = \\textcolor{{{color:primary.0}}}{{{eval:B}}}$ g.|Une boule pèse $\\textcolor{{{color:primary.0}}}{{{eval:B}}}$ g.}}","**Une étoile.** Deuxième pesée : ${{eval:(B+E)}} - {{eval:B}} = \\textcolor{{{color:primary.0}}}{{{eval:E}}}$ g.","**Vérification.** Première pesée : ${{a}} \\times {{eval:B}} + {{eval:E}} = {{eval:(a*B+E)}}$."]}},{"hint":"Imagine ${{a}}$ fois la deuxième pesée : combien pèserait-elle ? Compare-la à la première.","blanks":[{"expectedAnswer":"{{B}}","expectedErrors":[{"label":"Pesées soustraites telles quelles","answer":"{{eval:(a*B+b*E)-(B+E)}}","message":"On ne peut pas soustraire les pesées telles quelles : il resterait des boules et des étoiles. Imagine d'abord ${{a}}$ fois la deuxième pesée."},{"label":"Deuxième pesée partagée en deux","answer":"{{eval:(B+E)/2}}","message":"Une boule et une étoile n'ont pas la même masse : on ne peut pas partager la deuxième pesée en deux."},{"label":"Boule et étoile échangées","answer":"{{E}}","message":"C'est la masse d'une étoile : vérifie quelle case est celle de la boule."}]},{"expectedAnswer":"{{E}}","expectedErrors":[{"label":"Différence non partagée","answer":"{{eval:(b-a)*E}}","message":"C'est la masse de ${{eval:b-a}}$ étoiles : partage-la entre elles."},{"label":"Pesée partagée entre tous les objets","answer":"{{eval:(a*B+b*E)/(a+b)}}","message":"Les objets n'ont pas tous la même masse : on ne peut pas partager la première pesée en parts égales."},{"label":"Boule et étoile échangées","answer":"{{B}}","message":"C'est la masse d'une boule : vérifie quelle case est celle de l'étoile."}]}],"statement":"Les boules (B) sont toutes identiques, les étoiles (E) aussi. Voici deux pesées : chaque fois, la balance est en équilibre.\n\n{{if:c==0|```figure\nfenetre: 0 ; 9 ; -0.4 ; 3.6\ndescription: Première pesée : à gauche 2 boules B et 3 étoiles E, à droite une masse de {{eval:2*B+3*E}} g.\n---\nS1 = point(3.95, 0, visible=faux)\nS2 = point(5.05, 0, visible=faux)\nS3 = point(4.5, 1.15, visible=faux)\npolygone(S1, S2, S3, couleur=\"noir\", remplissage=\"gris\", opacite_fond=1)\nF1 = point(0.3, 1.2, visible=faux)\nF2 = point(8.7, 1.2, visible=faux)\nsegment(F1, F2, epaisseur=4)\nO0a = point(0.4, 1.3, visible=faux)\nO0b = point(1.2, 1.3, visible=faux)\nO0c = point(1.2, 2.2, visible=faux)\nO0d = point(0.4, 2.2, visible=faux)\npolygone(O0a, O0b, O0c, O0d, couleur=\"noir\", remplissage=\"jaune\", opacite_fond=0.3)\ntexte(0.8, 1.75, \"B\")\nO1a = point(1.3, 1.3, visible=faux)\nO1b = point(2.1, 1.3, visible=faux)\nO1c = point(2.1, 2.2, visible=faux)\nO1d = point(1.3, 2.2, visible=faux)\npolygone(O1a, O1b, O1c, O1d, couleur=\"noir\", remplissage=\"jaune\", opacite_fond=0.3)\ntexte(1.7, 1.75, \"B\")\nO2a = point(2.2, 1.3, visible=faux)\nO2b = point(3.0, 1.3, visible=faux)\nO2c = point(3.0, 2.2, visible=faux)\nO2d = point(2.2, 2.2, visible=faux)\npolygone(O2a, O2b, O2c, O2d, couleur=\"noir\", remplissage=\"jaune\", opacite_fond=0.3)\ntexte(2.6, 1.75, \"E\")\nO3a = point(3.1, 1.3, visible=faux)\nO3b = point(3.9, 1.3, visible=faux)\nO3c = point(3.9, 2.2, visible=faux)\nO3d = point(3.1, 2.2, visible=faux)\npolygone(O3a, O3b, O3c, O3d, couleur=\"noir\", remplissage=\"jaune\", opacite_fond=0.3)\ntexte(3.5, 1.75, \"E\")\nO4a = point(0.4, 2.3, visible=faux)\nO4b = point(1.2, 2.3, visible=faux)\nO4c = point(1.2, 3.2, visible=faux)\nO4d = point(0.4, 3.2, visible=faux)\npolygone(O4a, O4b, O4c, O4d, couleur=\"noir\", remplissage=\"jaune\", opacite_fond=0.3)\ntexte(0.8, 2.75, \"E\")\nD1 = point