e\", opacite_fond=0.3)\ntexte(3.5, 1.75, \"E\")\nO4a = point(0.4, 2.3, visible=faux)\nO4b = point(1.2, 2.3, visible=faux)\nO4c = point(1.2, 3.2, visible=faux)\nO4d = point(0.4, 3.2, visible=faux)\npolygone(O4a, O4b, O4c, O4d, couleur=\"noir\", remplissage=\"jaune\", opacite_fond=0.3)\ntexte(0.8, 2.75, \"E\")\nO5a = point(1.3, 2.3, visible=faux)\nO5b = point(2.1, 2.3, visible=faux)\nO5c = point(2.1, 3.2, visible=faux)\nO5d = point(1.3, 3.2, visible=faux)\npolygone(O5a, O5b, O5c, O5d, couleur=\"noir\", remplissage=\"jaune\", opacite_fond=0.3)\ntexte(1.7, 2.75, \"E\")\nO6a = point(2.2, 2.3, visible=faux)\nO6b = point(3.0, 2.3, visible=faux)\nO6c = point(3.0, 3.2, visible=faux)\nO6d = point(2.2, 3.2, visible=faux)\npolygone(O6a, O6b, O6c, O6d, couleur=\"noir\", remplissage=\"jaune\", opacite_fond=0.3)\ntexte(2.6, 2.75, \"E\")\nD1 = point(5.3, 1.3, visible=faux)\nD2 = point(7.9, 1.3, visible=faux)\nD3 = point(7.9, 2.2, visible=faux)\nD4 = point(5.3, 2.2, visible=faux)\npolygone(D1, D2, D3, D4, couleur=\"noir\", remplissage=\"jaune\", opacite_fond=0.3)\ntexte(6.6, 1.75, \"{{eval:3*B+4*E}} g\")\n```}}}}\n\n```figure\nfenetre: 0 ; 9 ; -0.4 ; 2.6\ndescription: Deuxième pesée : à gauche 1 boule B et 1 étoile E, à droite une masse de {{eval:B+E}} g.\n---\nS1 = point(3.95, 0, visible=faux)\nS2 = point(5.05, 0, visible=faux)\nS3 = point(4.5, 1.15, visible=faux)\npolygone(S1, S2, S3, couleur=\"noir\", remplissage=\"gris\", opacite_fond=1)\nF1 = point(0.3, 1.2, visible=faux)\nF2 = point(8.7, 1.2, visible=faux)\nsegment(F1, F2, epaisseur=4)\nO0a = point(0.4, 1.3, visible=faux)\nO0b = point(1.2, 1.3, visible=faux)\nO0c = point(1.2, 2.2, visible=faux)\nO0d = point(0.4, 2.2, visible=faux)\npolygone(O0a, O0b, O0c, O0d, couleur=\"noir\", remplissage=\"jaune\", opacite_fond=0.3)\ntexte(0.8, 1.75, \"B\")\nO1a = point(1.3, 1.3, visible=faux)\nO1b = point(2.1, 1.3, visible=faux)\nO1c = point(2.1, 2.2, visible=faux)\nO1d = point(1.3, 2.2, visible=faux)\npolygone(O1a, O1b, O1c, O1d, couleur=\"noir\", remplissage=\"jaune\", opacite_fond=0.3)\ntexte(1.7, 1.75, \"E\")\nD1 = point(5.3, 1.3, visible=faux)\nD2 = point(7.9, 1.3, visible=faux)\nD3 = point(7.9, 2.2, visible=faux)\nD4 = point(5.3, 2.2, visible=faux)\npolygone(D1, D2, D3, D4, couleur=\"noir\", remplissage=\"jaune\", opacite_fond=0.3)\ntexte(6.6, 1.75, \"{{eval:B+E}} g\")\n```\n\nQuelle est la masse d'une boule ? Quelle est la masse d'une étoile ?\n\nUne boule pèse $?$ g.\n\nUne étoile pèse $?$ g.","variables":[{"name":"c","expression":"0..2"},{"name":"a","expression":"eval:2*(1-min(abs(c-0),1))+2*(1-min(abs(c-1),1))+3*(1-min(abs(c-2),1))"},{"name":"b","expression":"eval:3*(1-min(abs(c-0),1))+4*(1-min(abs(c-1),1))+4*(1-min(abs(c-2),1))"},{"name":"B","expression":"20..50"},{"name":"E","expression":"20..50"}],"conditions":["B!=E"],"correction":{"steps":["**Une pesée imaginée.** Avec ${{a}}$ fois la deuxième pesée, on aurait ${{a}}$ boules et ${{a}}$ étoiles, de masse ${{a}} \\times {{eval:B+E}} = {{eval:a*(B+E)}}$ g.","**Comparer.** La première pesée a autant de boules, et ${{eval:b-a}}$ étoile{{if:b-a>1|s|}} de plus : ${{eval:a*B+b*E}} - {{eval:a*(B+E)}} = {{eval:(b-a)*E}}$ g.","**Une étoile.** {{if:b-a>1|${{eval:(b-a)*E}} \\div {{eval:b-a}} = \\textcolor{{{color:primary.0}}}{{{E}}}$ g.|Une étoile pèse $\\textcolor{{{color:primary.0}}}{{{E}}}$ g.}}","**Une boule.** Deuxième pesée : ${{eval:B+E}} - {{E}} = \\textcolor{{{color:primary.0}}}{{{B}}}$ g."]}},{"hint":"Compare les deux pesées : qu'y a-t-il en plus sur la première balance ?","blanks":[{"expectedAnswer":"{{eval:B/10;d}}","expectedErrors":[{"label":"Différence non partagée","answer":"{{eval:((a-1)*B)/10;d}}","message":"C'est la masse de ${{eval:a-1}}$ boules : partage-la entre elles."},{"label":"Pesée partagée entre tous les objets","answer":"{{eval:(a*B+E)/10/(a+1);d}}","message":"Les objets n'ont pas tous la même masse : on ne peut pas partager la première pesée en parts égales."},{"label":"Boule et étoile échangées","answer":"{{eval:E/10;d}}","message":"C'est la masse d'une étoile : vérifie quelle case est celle de la boule."}]},{"expectedAnswer":"{{eval:E/10;d}}","expectedErrors":[{"label":"Deuxième pesée partagée en deux","answer":"{{eval:(B+E)/10/2;d}}","message":"Une boule et une étoile n'ont pas la même masse : on ne peut pas partager la deuxième pesée en deux."},{"label":"Différence non partagée retirée","answer":"{{eval:(E-(a-2)*B)/10;d}}","message":"Tu as retiré la masse de ${{eval:a-1}}$ boules : sur la deuxième pesée, il n'y a qu'une boule."},{"label":"Boule et étoile échangées","answer":"{{eval:B/10;d}}","message":"C'est la masse d'une boule : vérifie quelle case est celle de l'étoile."}]}],"statement":"Les boules (B) sont toutes identiques, les étoiles (E) aussi. Voici deux pesées : chaque fois, la balance est en équilibre.\n\n{{if:a==2|```figure\nfenetre: 0 ; 9 ; -0.4 ; 2.6\ndescription: Première pesée : à gauche 2 boules B et 1 étoile E, à droite une masse de {{if:mod(2*B+E,10)==0|{{eval:(2*B+E)/10}} g|{{eval:floor((2*B+E)/10)}},{{eval:mod(2*B+E,10)}} g}}.\n---\nS1 = point(3.95, 0, visible=faux)\nS2 = point(5.05, 0, visible=faux)\nS3 = point(4.5, 1.15, visible=faux)\npolygone(S1, S2, S3, couleur=\"noir\", remplissage=\"gris\", opacite_fond=1)\nF1 = point(0.3, 1.2, visible=faux)\nF2 = point(8.7, 1.2, visible=faux)\nsegment(F1, F2, epaisseur=4)\nO0a = point(0.4, 1.3, visible=faux)\nO0b = point(1.2, 1.3, visible=faux)\nO0c = point(1.2, 2.2, visible=faux)\nO0d = point(0.4, 2.2, visible=faux)\npolygone(O0a, O0b, O0c, O0d, couleur=\"noir\", remplissage=\"jaune\", opacite_fond=0.3)\ntexte(0.8, 1.75, \"B\")\nO1a = point(1.3, 1.3, visible=faux)\nO1b = point(2.1, 1.3, visible=faux)\nO1c = point(2.1, 2.2, visible=faux)\nO1d = point(1.3, 2.2, visible=faux)\npolygone(O1a, O1b, O1c, O1d, couleur=\"noir\", remplissage=\"jaune\", opacite_fond=0.3)\ntexte(1.7, 1.75, \"B\")\nO2a = point(2.2, 1.3, visible=faux)\nO2b = point(3.0, 1.3, visible=faux)\nO2c = point(3.0, 2.2, visible=faux)\nO2d = point(2.2, 2.2, visible=faux)\npolygone(O2a, O2b, O2c, O2d, couleur=\"noir\", remplissage=\"jaune\", opacite_fond=0.3)\ntexte(2.6, 1.75, \"E\")\nD1 = point(5.3, 1.3, visible=faux)\nD2 = point(7.9, 1.3, visible=faux)\nD3 = point(7.9, 2.2, visible=faux)\nD4 = point(5.3, 2.2, visible=faux)\npolygone(D1, D2, D3, D4, couleur=\"noir\", remplissage=\"jaune\", opacite_fond=0.3)\ntexte(6.6, 1.75, \"{{if:mod(2*B+E,10)==0|{{eval:(2*B+E)/10}} g|{{eval:floor((2*B+E)/10)}},{{eval:mod(2*B+E,10)}} g}}\")\n```|{{if:a==3|```figure\nfenetre: 0 ; 9 ; -0.4 ; 2.6\ndescription: Première pesée : à gauche 3 boules B et 1 étoile E, à droite une masse de {{if:mod(3*B+E,10)==0|{{eval:(3*B+E)/10}} g|{{eval:floor((3*B+E)/10)}},{{eval:mod(3*B+E,10)}} g}}.\n---\nS1 = point(3.95, 0, visible=faux)\nS2 = point(5.05, 0, visible=faux)\nS3 = point(4.5, 1.15, visible=faux)\npolygone(S1, S2, S3, couleur=\"noir\", remplissage=\"gris\", opacite_fond=1)\nF1 = point(0.3, 1.2, visible=faux)\nF2 = point(8.7, 1.2, visible=faux)\nsegment(F1, F2, epaisseur=4)\nO0a = point(0.4, 1.3, visible=faux)\nO0b = point(1.2, 1.3, visible=faux)\nO0c = point(1.2, 2.2, visible=faux)\nO0d = point(0.4, 2.2, visible=faux)\npolygone(O0a, O0b, O0c, O0d, couleur=\"noir\", remplissage=\"jaune\", opacite_fond=0.3)\ntexte(0.8, 1.75, \"B\")\nO1a = point(1.3, 1.3, visible=faux)\nO1b = point(2.1, 1.3, visible=faux)\nO1c = point(2.1, 2.2, visible=faux)\nO1d = point(1.3, 2.2, visible=faux)\npolygone(O1a, O1b, O1c, O1d, couleur=\"noir\", remplissage=\"jaune\", opacite_fond=0.3)\ntexte(1.7, 1.75, \"B\")\nO2a = point(2.2, 1.3, visible=faux)\nO2b = point(3.0, 1.3, visible=faux)\nO2c = point(3.0, 2.2, visible=faux)\nO2d = point(2.2, 2.2, visible=faux)\npolygone(O2a, O2b, O2c, O2d, couleur=\"noir\", remplissage=\"jaune\", opacite_fond=0.3)\ntexte(2.6, 1.75, \"B\")\nO3a = point(3.1, 1.3, visible=faux)\nO3b = point(3.9, 1.3, visible=faux)\nO3c = point(3.9, 2.2, visible=faux)\nO3d = point(3.1, 2.2, visible=faux)\npolygone(O3a, O3b, O3c, O3d, couleur=\"noir\", rempli