ible=faux)\nO4b = point(1.2, 2.3, visible=faux)\nO4c = point(1.2, 3.2, visible=faux)\nO4d = point(0.4, 3.2, visible=faux)\npolygone(O4a, O4b, O4c, O4d, couleur=\"noir\", remplissage=\"jaune\", opacite_fond=0.3)\ntexte(0.8, 2.75, \"E\")\nD1 = point(5.3, 1.3, visible=faux)\nD2 = point(7.9, 1.3, visible=faux)\nD3 = point(7.9, 2.2, visible=faux)\nD4 = point(5.3, 2.2, visible=faux)\npolygone(D1, D2, D3, D4, couleur=\"noir\", remplissage=\"jaune\", opacite_fond=0.3)\ntexte(6.6, 1.75, \"{{if:mod(4*B+E,10)==0|{{eval:(4*B+E)/10}} g|{{eval:floor((4*B+E)/10)}},{{eval:mod(4*B+E,10)}} g}}\")\n```}}}}\n\n```figure\nfenetre: 0 ; 9 ; -0.4 ; 2.6\ndescription: Deuxième pesée : à gauche 1 boule B et 1 étoile E, à droite une masse de {{if:mod(B+E,10)==0|{{eval:(B+E)/10}} g|{{eval:floor((B+E)/10)}},{{eval:mod(B+E,10)}} g}}.\n---\nS1 = point(3.95, 0, visible=faux)\nS2 = point(5.05, 0, visible=faux)\nS3 = point(4.5, 1.15, visible=faux)\npolygone(S1, S2, S3, couleur=\"noir\", remplissage=\"gris\", opacite_fond=1)\nF1 = point(0.3, 1.2, visible=faux)\nF2 = point(8.7, 1.2, visible=faux)\nsegment(F1, F2, epaisseur=4)\nO0a = point(0.4, 1.3, visible=faux)\nO0b = point(1.2, 1.3, visible=faux)\nO0c = point(1.2, 2.2, visible=faux)\nO0d = point(0.4, 2.2, visible=faux)\npolygone(O0a, O0b, O0c, O0d, couleur=\"noir\", remplissage=\"jaune\", opacite_fond=0.3)\ntexte(0.8, 1.75, \"B\")\nO1a = point(1.3, 1.3, visible=faux)\nO1b = point(2.1, 1.3, visible=faux)\nO1c = point(2.1, 2.2, visible=faux)\nO1d = point(1.3, 2.2, visible=faux)\npolygone(O1a, O1b, O1c, O1d, couleur=\"noir\", remplissage=\"jaune\", opacite_fond=0.3)\ntexte(1.7, 1.75, \"E\")\nD1 = point(5.3, 1.3, visible=faux)\nD2 = point(7.9, 1.3, visible=faux)\nD3 = point(7.9, 2.2, visible=faux)\nD4 = point(5.3, 2.2, visible=faux)\npolygone(D1, D2, D3, D4, couleur=\"noir\", remplissage=\"jaune\", opacite_fond=0.3)\ntexte(6.6, 1.75, \"{{if:mod(B+E,10)==0|{{eval:(B+E)/10}} g|{{eval:floor((B+E)/10)}},{{eval:mod(B+E,10)}} g}}\")\n```\n\nQuelle est la masse d'une boule ? Quelle est la masse d'une étoile ?\n\nUne boule pèse $?$ g.\n\nUne étoile pèse $?$ g.","variables":[{"name":"a","expression":"2..4"},{"name":"B","expression":"201..499"},{"name":"E","expression":"201..499"}],"conditions":["B!=E","mod(B,10)!=0","mod(E,10)!=0"],"correction":{"steps":["**Comparer les pesées.** La première a ${{eval:a-1}}$ boule{{if:a>2|s|}} de plus que la deuxième ; tout le reste est pareil. La différence des masses, c'est donc ${{eval:a-1}}$ boule{{if:a>2|s|}} : ${{eval:(a*B+E)/10;d}} - {{eval:(B+E)/10;d}} = {{eval:((a-1)*B)/10;d}}$.","**Une boule.** {{if:a>2|${{eval:((a-1)*B)/10;d}} \\div {{eval:a-1}} = \\textcolor{{{color:primary.0}}}{{{eval:B/10;d}}}$ g.|Une boule pèse $\\textcolor{{{color:primary.0}}}{{{eval:B/10;d}}}$ g.}}","**Une étoile.** Deuxième pesée : ${{eval:(B+E)/10;d}} - {{eval:B/10;d}} = \\textcolor{{{color:primary.0}}}{{{eval:E/10;d}}}$ g.","**Vérification.** Première pesée : ${{a}} \\times {{eval:B/10;d}} + {{eval:E/10;d}} = {{eval:(a*B+E)/10;d}}$."]}},{"statement":"Les boules (B) sont toutes identiques, les étoiles (E) aussi. Voici deux pesées : chaque fois, la balance est en équilibre.\n\n{{if:a==2|```figure\nfenetre: 0 ; 9 ; -0.4 ; 2.6\ndescription: Première pesée : à gauche 2 boules B et 1 étoile E, à droite une masse de {{if:mod(2*B+E,100)==0|{{eval:(2*B+E)/100}} kg|{{if:mod(2*B+E,10)==0|{{eval:floor((2*B+E)/100)}},{{eval:mod(2*B+E,100)/10}} kg|{{eval:floor((2*B+E)/100)}},{{if:mod(2*B+E,100)<10|0|}}{{eval:mod(2*B+E,100)}} kg}}}}.\n---\nS1 = point(3.95, 0, visible=faux)\nS2 = point(5.05, 0, visible=faux)\nS3 = point(4.5, 1.15, visible=faux)\npolygone(S1, S2, S3, couleur=\"noir\", remplissage=\"gris\", opacite_fond=1)\nF1 = point(0.3, 1.2, visible=faux)\nF2 = point(8.7, 1.2, visible=faux)\nsegment(F1, F2, epaisseur=4)\nO0a = point(0.4, 1.3, visible=faux)\nO0b = point(1.2, 1.3, visible=faux)\nO0c = point(1.2, 2.2, visible=faux)\nO0d = point(0.4, 2.2, visible=faux)\npolygone(O0a, O0b, O0c, O0d, couleur=\"noir\", rempli